import turingMark from "@/assets/logos/turing.svg";
import turingMarkSmall from "@/assets/logos/turing-small.svg";

interface TurLogoProps {
    readonly size?: number;
    readonly className?: string;
}

/**
 * The Viglet Turing mark: an isometric cube with its front-top corner cut in the
 * angle of the Viglet V and "Tu" on its left face. The SVGs are generated by
 * make_marks.py in the alegauss/visibility repository (marca/logo/); copy them
 * over after regenerating, do not edit them by hand. Below 56 px the cube is drawn
 * without the symbol, which stops reading there.
 */
export function TurLogo({ size = 48, className }: TurLogoProps) {
    return (
        <img
            src={size < 56 ? turingMarkSmall : turingMark}
            alt="Viglet Turing"
            width={size}
            height={size}
            className={className}
            draggable={false}
        />
    );
}
